	if (q.operation == W10DiagnosticsOperation::Metrics) { if(!p.read_metrics||!p.read_percentiles||!p.read_latency_mean||!p.read_latency_samples||!p.read_kad6_metrics)return false;W10MetricsSnapshot s;if(!p.read_metrics(p.context,s))return false;std::uint32_t p50=0,p95=0,p99=0,mean=0;p.read_percentiles(p.context,p50,p95,p99);mean=p.read_latency_mean(p.context);const int n=p.read_latency_samples(p.context);r.body=Metrics(s,n,mean,p50,p95,p99);try{std::string k;if(!p.read_kad6_metrics(p.context,k))return false;r.body+=k;}catch(...){ }r.header=H(r.body,"Content-Type: text/plain; version=0.0.4; charset=utf-8\r\nCache-Control: no-store\r\nAccess-Control-Allow-Origin: *\r\n");return true; }
	if (q.operation == W10DiagnosticsOperation::Log) { if(!p.read_log)return false;const int n=q.log_n<=0?100:q.log_n>500?500:q.log_n; std::vector<std::string> v;if(!p.read_log(p.context,n,v))return false;r.body="{\"items\":[";for(std::size_t i=0;i<v.size();++i){if(i)r.body+=',';r.body+='"';E(r.body,v[i]);r.body+='"';}r.body+="]}";r.header=H(r.body,"Content-Type: application/json; charset=utf-8\r\nCache-Control: no-store\r\nAccess-Control-Allow-Origin: *\r\n");return true; }
	if (q.operation == W10DiagnosticsOperation::Debug) { W10DebugSnapshot s;if(!p.read_debug||!p.read_debug(p.context,s))return false;r.body=Debug(s);r.header=H(r.body,"Content-Type: application/json\r\nAccess-Control-Allow-Origin: http://127.0.0.1\r\nX-Content-Type-Options: nosniff\r\n");return true; }
	if (q.operation == W10DiagnosticsOperation::Ipv6Echo) { W10Ipv6EchoResult s;if(!p.run_ipv6_echo||!p.run_ipv6_echo(p.context,q,s))return false;r.body=Ipv6Echo(s);r.header=HS(r.body,s.success?"200 OK":"409 Conflict","Content-Type: application/json\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\n");return true; } return false;
